function educationPracticeView(){
 return '<section class="education-practice-shell" aria-label="Education Practice"><header class="education-practice-bar"><div><h1>Education Practice</h1><p>Try 120 questions · Leave comments to help improve them.</p></div>'+button('‹ Main Menu','education-practice-back','btn subtle')+'</header><iframe id="education-practice-frame" title="Education Practice — all 120 questions" allow="web-share"></iframe></section>';
}
function finishEducationPractice(){ui.educationPractice=false;ui.home=true;render();document.querySelector('[data-action=education-practice]')?.focus();}
function requestEducationPracticeClose(){
 const frame=$('#education-practice-frame');
 if(frame?.contentWindow)frame.contentWindow.postMessage({type:'stm-education-practice-request-close'},location.origin==='null'?'*':location.origin);
}
window.addEventListener('message',event=>{
 if(!ui.educationPractice||event.source!==$('#education-practice-frame')?.contentWindow||event.origin!==location.origin)return;
 const data=event.data;
 if(data?.type==='stm-education-practice-close')finishEducationPractice();
 else if(data?.type==='stm-education-practice-audio'&&Object.hasOwn(Q.catalog,data.questionId)&&typeof data.key==='string'&&data.key.length<=160&&['closed','hintUsed','moreHintViewed'].every(key=>typeof data[key]==='boolean')){
  if(data.record!==undefined&&!validPracticeAudioRecord(data.record))return;
  practiceAudioState=data.record?AP.questionState(data.key,data.record,{closed:data.closed}):{key:data.key,closed:data.closed,hintUsed:data.hintUsed,moreHintViewed:data.moreHintViewed};syncMusic();
 }
 else if(data?.type==='stm-education-practice-audio-clear'){practiceAudioState=null;syncMusic();}
});
function validPracticeAudioRecord(record){
 const types=['GAME_POLICY_APPLIED','HINT_REVEALED','MORE_HINT_OPENED','ANSWER_SUBMITTED','FINAL_REVEALED','STEPS_TOGGLED','FOUNDATION_OPENED'];
 const id=value=>typeof value==='string'&&value.length>0&&value.length<=200&&!/[\x00-\x1f\x7f]/.test(value);
 return record&&['pending','correct','revealed'].includes(record.status)&&Array.isArray(record.events)&&record.events.length<=10000&&Array.isArray(record.attempts)&&record.attempts.length<=10000&&record.events.every(e=>e&&types.includes(e.type)&&(e.type!=='ANSWER_SUBMITTED'||id(e.attemptId)))&&record.attempts.every(a=>a&&id(a.id)&&typeof a.correct==='boolean')&&typeof record.hintState?.hintUsed==='boolean'&&typeof record.hintState?.moreHintViewed==='boolean';
}
function scheduleMenu(){
 clearTimeout(menuTimer);
 if(!ui.home||document.hidden||!motionAllowed()||!$('.illustrated-home'))return;
 menuTimer=setTimeout(()=>{
  if($('#dialog').open||$('.main-menu-actions:hover')||$('.main-menu-actions:focus-within')){scheduleMenu();return;}
  selectMenuScene((ui.menuScene+1)%V.menuScenes.length);
 },V.timing.menu);
}
async function selectMenuScene(index,manual=false){
 const scene=V.menuScenes[index],home=$('.illustrated-home');
 if(!scene||!home){scheduleMenu();return;}
 if(index===ui.menuScene){++menuGeneration;scheduleMenu();return;}
 clearTimeout(menuTimer);const generation=++menuGeneration;
 // Fixed scene images keep a fading layer's source intact during rapid selection.
 const next=home.querySelector('.menu-backdrop[data-scene-index="'+index+'"]');
 try{
  if(window.STMHosted?.manager){await Promise.all([...home.querySelectorAll('[data-scene-index="'+index+'"]')].filter(el=>el.tagName==='IMG').map(el=>window.STMHosted.imageElement(el)));}
  if(next.decode)await next.decode();
  else await new Promise((resolve,reject)=>{if(next.complete&&next.naturalWidth)resolve();else{next.onload=resolve;next.onerror=reject;}});
 }catch(_){if(generation===menuGeneration){if(manual)toast('Artwork could not be loaded. Choose another scene.',true);scheduleMenu();}return;}
 if(generation!==menuGeneration||!home.isConnected)return;
 if(!manual&&(document.hidden||!motionAllowed()||$('#dialog').open||$('.main-menu-actions:hover')||$('.main-menu-actions:focus-within'))){scheduleMenu();return;}
 home.querySelectorAll('.menu-backdrop,.menu-ambience').forEach(el=>el.classList.toggle('active',Number(el.dataset.sceneIndex)===index));
 ui.menuScene=index;home.dataset.art=scene.id;
 home.querySelector('#home-scene-name').textContent=scene.label;
 home.querySelectorAll('.scene-choice').forEach((el,i)=>el.setAttribute('aria-pressed',String(i===index)));
 scheduleMenu();
}
function artifactsButton(cls='btn small'){const items=E.ownedArtifacts(run);return !run.artifactState?'':button((items[0]?'<img src="assets/'+items[0].icon+'" width="28" height="28" alt="" aria-hidden="true">':'')+'Artifacts · '+items.length,'artifacts',cls+' artifacts-trigger','aria-label="Your artifacts, '+items.length+' owned"');}
function showArtifacts(){ui.modal='artifacts';modal('Your Artifacts',AU.inventory(run,{esc,button}),true);}
function artifactView(){return AU.render(run,ui.artifactChoice,{esc,button});}
function runStatus(map=false){return '<div class="run-status"><span class="hp-pill">'+icon('heart')+' '+run.hp+'<small>/ '+run.maxHp+'</small></span><span class="gold-pill">'+icon('coin')+' '+(run.gold||0)+' <small>Gold</small></span>'+button(icon('cards')+' '+run.deck.length+' cards','deck','btn small')+artifactsButton()+(map?'':button('Calculations','calculations','btn small subtle'))+button('Menu','home','btn small subtle')+'</div>';}
function runTop(showStatus=true){return '<div class="run-top"><div><p class="eyebrow">STAGE '+(run.stage+1)+' / 2 · ROOM '+(run.depth+1)+' / '+E.getMap(run).floors+(balanceLabel()?' · '+esc(balanceLabel()):'')+'</p><h1>'+esc(C.stages[run.stage].name)+'</h1>'+(run.economyState&&!run.balanceState?'<small>Economy test · '+esc(run.economyState.difficulty)+' · Combat baseline 2.24.0</small>':'')+'</div>'+(showStatus?runStatus():'')+'</div>';}
function mapIcon(type){return '<img class="map-room-art" src="assets/'+V.mapIcons[type]+'" width="64" height="64" alt="" decoding="async">';}
function mapView(){
 const map=E.getMap(run),available=E.availableNodes(run),allowed=new Set(available.map(n=>n.id));
 const roomNames={battle:'Battle',elite:'Elite',boss:'Boss',camp:'Rest',event:'Mystery',shop:'Shop'};
 const visited=new Set(run.route?.path||map.nodes.filter(n=>n.depth<run.depth&&map.nodes.filter(x=>x.depth===n.depth).length===1).map(n=>n.id));
 const path=run.route?.path||[],position=path.at(-1);
 const connections=map.nodes.flatMap(n=>n.next.map(id=>{
  const target=map.nodes.find(x=>x.id===id),index=path.indexOf(n.id);
  const status=index>=0&&path[index+1]===id?' travelled':n.id===position&&allowed.has(id)?' open':'';
  const mid=(n.y+target.y)/2;
  return '<path class="dungeon-path'+status+'" d="M'+n.x+' '+n.y+' C'+n.x+' '+mid+' '+target.x+' '+mid+' '+target.x+' '+target.y+'"/>';
 })).join('');
 const origin=run.depth===0?available.map(n=>'<path class="dungeon-path open" d="M50 96 C50 92 '+n.x+' 92 '+n.x+' '+n.y+'"/>').join(''):'';
 const rooms=map.nodes.map(n=>{
  const ready=allowed.has(n.id),done=visited.has(n.id),here=n.id===position;
  const state=ready?'Enter Room':here?'You Are Here':done?'Cleared':n.depth<run.depth?'Passed':'Locked';
  return '<button type="button" class="dungeon-room '+n.type+(ready?' available':done?' visited':' locked')+(here?' is-position':'')+'" data-id="'+n.id+'" '+(ready?'data-action="node"':'disabled')+' style="left:'+n.x+'%;top:'+n.y+'%" aria-label="Level '+(n.depth+1)+': '+roomNames[n.type]+'. '+state+'."><span class="room-seal">'+mapIcon(n.type)+(done?'<span class="room-check">'+icon('check')+'</span>':'')+'</span><span class="room-name">'+roomNames[n.type]+'</span><span class="room-state">'+state+'</span></button>';
 }).join('');
 const legend=[['battle','Battle'],['elite','Elite'],['camp','Rest'],['shop','Shop'],['event','Mystery'],['boss','Boss']];
 const levels=Array.from({length:map.floors},(_,i)=>{const row=map.nodes.find(n=>n.depth===i);return '<span class="atlas-level" style="top:'+row.y+'%" aria-hidden="true"><span class="atlas-coordinate">'+'Floor '+String(i+1).padStart(2,'0')+'</span></span>';}).join('');
 return '<section class="dungeon-layout" data-stm-map aria-label="Branching Dungeon Map"><div class="map-overview">'+runTop(false)+'<aside class="dungeon-sidebar map-rail ornate-panel" aria-labelledby="map-legend-title"><p class="eyebrow">DUNGEON ATLAS</p><h2 id="map-legend-title">The path ahead</h2><p class="map-rail-intro">Select a room icon<br>to enter the dungeon.</p><p class="route-key"><span class="route-key-open">Next room</span><span class="route-key-done">Your route</span><span class="route-key-locked">Other paths</span></p><h3 class="map-legend-heading">Rooms</h3><ul class="route-legend">'+legend.map(([symbol,name])=>'<li>'+mapIcon(symbol)+'<span>'+name+'</span></li>').join('')+'</ul></aside></div><div class="map-chart"><div class="atlas-frame"><div class="atlas-scroll" role="region" tabindex="0" aria-label="Dungeon map. Scroll upward to see all levels. Only room types are shown."><div class="dungeon-atlas '+(map.floors===10?'ten-floor':'')+'" role="group" aria-label="Map '+esc(C.stages[run.stage].name)+'. Follow the paths from bottom to top."><span class="atlas-inscription">THE DUNGEON AWAITS</span><span class="atlas-compass" aria-hidden="true">N</span>'+levels+'<svg class="dungeon-connections" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">'+connections+origin+'</svg>'+rooms+'<span class="map-origin">'+(run.depth?'FOLLOW YOUR CHOSEN PATH':'YOUR JOURNEY BEGINS HERE')+'</span></div></div></div></div></section>';
}

function cardDisplayPlan(c){return E.cardDisplayPlan(c,run);}
function cardDefinition(c){return E.definition(c,run);}
function statusBadge(x,who,overview=false){
 const kind=CS.text(x.kind,QL.language()),details=[x.label+': '+x.value,x.measure,x.summary,x.timing,kind,x.description].join('. ');
 return button('<span class="status-art"><img data-status-icon="'+x.id+'" src="'+esc(x.icon)+'" width="56" height="56" alt=""><b>'+x.value+'</b></span><span class="status-name">'+esc(x.label)+'</span><span class="status-measure">'+esc(overview?x.measure:x.inlineMeasure)+'</span>'+(overview?'<span class="status-summary">'+esc(x.summary)+'</span><span class="status-timing">'+esc(x.timing)+'</span><span class="status-kind">'+kind+'</span>':''),'status-details','combat-status-badge '+x.kind+(overview?' status-overview-item':''),'data-who="'+who+'" data-id="'+x.id+'" aria-label="'+esc(details)+'" title="'+esc(details)+'"');
}
function statusItems(who){return CS.view(run,who,QL.language()).sort((a,b)=>({debuff:0,buff:1,queued:2}[a.kind]-{debuff:0,buff:1,queued:2}[b.kind]));}
function combatStatus(who){
 const items=statusItems(who),owner=who==='player'?C.MC.name:C.enemies[run.battle.enemyId].name;
 return '<div class="combat-status-group" data-status-owner="'+who+'"><div class="combat-status-rack" role="group" aria-label="'+esc(owner+' · '+CS.text('title',QL.language()))+'">'+items.map(x=>statusBadge(x,who)).join('')+'</div>'+(items.length?button('<strong>'+items.length+'</strong><span>'+esc(CS.text('all',QL.language()))+'</span>','statuses','status-overview-trigger','data-who="'+who+'" aria-label="'+esc(CS.text('all',QL.language())+': '+items.length+' · '+owner)+'"'):'')+'</div>';
}
function combatGroups(){
 const groups=[];
 for(const entry of CL.entries(run)){const last=groups.at(-1);if(last&&last.turn===entry.turn&&last.actor===entry.actor)last.entries.push(entry);else groups.push({turn:entry.turn,actor:entry.actor,name:entry.actorName,entries:[entry]});}
 return groups;
}
function combatJournal(full=false){
 const groups=combatGroups(),latest=groups.at(-1),other=latest?groups.findLast(g=>g.actor!==latest.actor):null,shown=full?groups:latest?[...(other?[other]:[]),latest]:[];
 const rows=shown.map(g=>'<li><strong>Turn '+g.turn+' ('+esc(g.name)+')</strong><ul>'+g.entries.slice(full?0:-2).map(e=>'<li><span class="journal-source">'+esc(e.label)+'</span>: '+esc(e.summary)+'</li>').join('')+'</ul></li>').join('');
 return '<ol class="combat-journal-list'+(full?' full':'')+'">'+(rows||'<li class="journal-empty">'+esc(run.battle.log[0]||'Choose your next move.')+'</li>')+'</ol>';
}
