 if(!retainActors){actorAnimation?.destroy();actorAnimation=null;heroAnimation?.destroy();heroAnimation=null;actorView=null;}
 R.hide();CU.hide();
 clearTimeout(menuTimer);menuGeneration++;
 clearBattleFeedback();
