document.addEventListener('input',event=>{
 const el=event.target;if(el.id==='card-search'){if(event.isComposing)return;const start=el.selectionStart;ui.libraryQuery=el.value;ui.libraryPage=0;showLibrary();const input=$('#card-search');input.focus();try{input.setSelectionRange(start,start);}catch(_){}return;}if(!['music-volume','sfx-volume','voice-volume'].includes(el.id))return;
 const value=Number(el.value)/100,key=({'music-volume':'musicVolume','sfx-volume':'sfxVolume','voice-volume':'voiceVolume'})[el.id];
 settings[key]=value;syncMusic();save();const output=$('#'+el.id+'-value');if(output)output.textContent=Math.round(value*100)+'%';
});
document.addEventListener('keydown',event=>{if(event.target.matches('input,textarea,select')||event.ctrlKey||event.metaKey||event.altKey||event.repeat||$('#dialog').open||ui.home||run?.scene!=='battle')return;const key=event.key.toLowerCase();let action;if(key==='r')action='forecast';if(key==='e')action='end-turn';if(action){event.preventDefault();document.querySelector('[data-action="'+action+'"]:not(:disabled)')?.click();}if(/^[0-9]$/.test(key)){event.preventDefault();const c=run.battle.hand[key==='0'?9:Number(key)-1];if(c)document.querySelector('[data-action="play"][data-id="'+c.uid+'"]:not(:disabled)')?.click();}});
// One listener for the whole app; no per-render timers or event handlers.
let pointerFrame=0,pointerX=0,pointerY=0;
function motionAllowed(){return settings.motion&&!(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches);}
document.addEventListener('pointermove',event=>{
 if(!ui.home||!motionAllowed()||event.pointerType==='touch')return;
 pointerX=event.clientX/window.innerWidth-.5;pointerY=event.clientY/window.innerHeight-.5;
 if(!pointerFrame)pointerFrame=requestAnimationFrame(()=>{pointerFrame=0;document.documentElement.style.setProperty('--pointer-x',pointerX.toFixed(3));document.documentElement.style.setProperty('--pointer-y',pointerY.toFixed(3));});
},{passive:true});
document.addEventListener('pointerleave',()=>{document.documentElement.style.setProperty('--pointer-x','0');document.documentElement.style.setProperty('--pointer-y','0');});
window.matchMedia?.('(prefers-reduced-motion: reduce)').addEventListener?.('change',()=>{cardMotion.cancel();syncActorMotion();scheduleMenu();});
CU.bind(document);
render();
